package com.littlemakers.village.nativeapp;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
/** Original offline K–10 starter trail. Back stays within the level/subject/mission hierarchy. */
public final class SchoolTrailActivity extends Activity {
 private GameDatabase db;private PlayerWallet wallet;private ProgressManager progress;private SoundEngine sound;private OfflineNarrator narrator;private ThemeManager theme;private NativeStageSurface stage;private SchoolAnswers answers;private SchoolPlayView board;private LinearLayout root,body;private TextView prompt,message,guide;private Button next;private SchoolContent.Question question;private String screen="grades";private int grade,subject,mission,companion;private boolean active,replaying;private long resetGeneration;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);db=GameDatabase.create(this);wallet=new PlayerWallet(db);progress=new ProgressManager(db);sound=new SoundEngine(this);narrator=new OfflineNarrator(this,()->{if(message!=null)message.setText("An offline voice is unavailable. The prompt is ready to read.");});companion=Math.max(0,Math.min(7,getSharedPreferences("school_trail",0).getInt("companion",0)));resetGeneration=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(saved!=null){grade=saved.getInt("grade");subject=saved.getInt("subject");mission=saved.getInt("mission");screen=saved.getString("screen","grades");replaying=saved.getBoolean("replaying",false);}render();if(Build.VERSION.SDK_INT>=33)Api33.register(this);}
 static final class Api33{static void register(SchoolTrailActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::back);}}
 private int dp(float n){return theme.dp(n);}private boolean reduced(){return getSharedPreferences("family",0).getBoolean("reduce_motion",false)||android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}
 private TextView text(String s,int sp,boolean bold){TextView v=GameUi.label(this,theme,s,sp,bold);v.setPadding(dp(8),dp(7),dp(8),dp(7));return v;}
 private Button button(String s,Runnable run){Button b=new Button(this);b.setText(s);b.setAllCaps(false);GameUi.control(b,theme);b.setPadding(dp(8),dp(4),dp(8),dp(4));b.setOnClickListener(v->{sound.tap();v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);run.run();});return b;}
 private void base(String title){if(board!=null){board.stop();board=null;}if(stage!=null){stage.pauseStage();stage=null;}theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹",this::back);back.setContentDescription("Back to previous learning screen");bar.addView(back,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView heading=text(title,22,true);heading.setGravity(Gravity.CENTER);bar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));Button close=button("⌂",this::finish);close.setContentDescription("Close Learning trail and return to the calling screen");bar.addView(close,new LinearLayout.LayoutParams(dp(64),dp(64)));root.addView(bar);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(8),dp(12),dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 private void scene(FrameLayout frame){if(((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getDeviceConfigurationInfo().reqGlEsVersion<0x20000)return;final NativeStageSurface[]holder={null};stage=new NativeStageSurface(this,theme.dark,()->{if(stage==holder[0]){NativeStageSurface old=stage;stage=null;old.pauseStage();frame.removeView(old);if(board!=null)board.stage(null);}});holder[0]=stage;frame.addView(stage,new FrameLayout.LayoutParams(-1,-1));}
 private void render(){if(grade<0||grade>10||subject<0||subject>2||mission<0||mission>=SchoolContent.count(subject)){grade=subject=mission=0;screen="grades";}if(screen.equals("subjects"))subjects(grade);else if(screen.equals("missions"))missions(subject);else if(screen.equals("mission"))play(mission,replaying);else grades();}
 void grades(){screen="grades";question=null;base("Learning trail");body.addView(text("Meet your adventure crew",24,true));FrameLayout preview=new FrameLayout(this);body.addView(preview,new LinearLayout.LayoutParams(-1,dp(180)));scene(preview);if(stage!=null){List<SceneFrame.Node>nodes=new ArrayList<>();for(int i=0;i<8;i++)nodes.add(new SceneFrame.Node(SceneFrame.ACTOR,80+i%4*160,70+i/4*130,48,48,40,CompanionCast.COLORS[i],i,true));stage.submit(new SceneFrame(nodes,theme.background,280,"welcome",false));}guide=text(CompanionCast.NAMES[companion]+" is your guide · tap a friend",15,true);body.addView(guide);if(stage!=null)stage.setOnTouchListener((v,e)->{if(!screen.equals("grades"))return false;if(e.getActionMasked()==MotionEvent.ACTION_UP){int column=Math.max(0,Math.min(3,(int)(e.getX()*4/Math.max(1,v.getWidth())))),row=Math.max(0,Math.min(1,(int)(e.getY()*2/Math.max(1,v.getHeight()))));chooseGuide(row*4+column);v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);sound.tap();}return true;});HorizontalScrollView friends=new HorizontalScrollView(this);friends.setHorizontalScrollBarEnabled(false);LinearLayout names=new LinearLayout(this);for(int i=0;i<8;i++){final int who=i;Button choose=button(CompanionCast.NAMES[i].split(" ")[0],()->{chooseGuide(who);});choose.setContentDescription("Choose "+CompanionCast.NAMES[i]+" as your guide");names.addView(choose,new LinearLayout.LayoutParams(dp(96),dp(64)));}friends.addView(names);body.addView(friends);body.addView(text("Choose your level · 264 starter activities",18,true));View[]levels=new View[11];for(int i=0;i<11;i++){final int level=i;levels[i]=GameUi.card(this,theme,SchoolContent.grade(i),"24 maths, word & science missions",i%2==0?22:23,CompanionCast.COLORS[i%8],false,false,()->subjects(level));}LinearLayout grid=GameUi.grid(this);GameUi.cells(grid,levels,2,theme,122);body.addView(grid);body.addView(button("Creative adventures & studios",()->startActivity(new Intent(this,QuestActivity.class))));body.addView(text("These are original starter activities, not a full school syllabus. Choose any level and explore at your own pace.",13,false));}
 private void chooseGuide(int who){companion=Math.max(0,Math.min(7,who));getSharedPreferences("school_trail",0).edit().putInt("companion",companion).apply();guide.setText(CompanionCast.NAMES[companion]+" is your guide");if(stage!=null)stage.react(80+companion%4*160,70+companion/4*130);}
 void subjects(int level){grade=Math.max(0,Math.min(10,level));screen="subjects";question=null;base(SchoolContent.grade(grade));body.addView(text("Choose a world to change",24,true));for(int i=0;i<3;i++){final int mode=i;View card=GameUi.card(this,theme,SchoolContent.SUBJECTS[i],SchoolContent.count(i)+" playable missions",i==0?23:i==1?22:21,new int[]{0xffe4bd7b,0xffb7a4d9,0xff86b9d9}[i],true,false,()->missions(mode));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));body.addView(card,p);}}
 void missions(int mode){subject=Math.max(0,Math.min(2,mode));screen="missions";question=null;base(SchoolContent.grade(grade)+" · "+SchoolContent.SUBJECTS[subject]);body.addView(text("Choose an expedition",22,true));if(subject==2)body.addView(button("Moon expedition · watch and choose",()->startActivity(new Intent(this,CinemaActivity.class))));View[]items=new View[SchoolContent.count(subject)];for(int i=0;i<items.length;i++){final int index=i;SchoolContent.Question q=SchoolContent.at(grade,subject,i);items[i]=GameUi.card(this,theme,"Mission "+(i+1),q.topic+(complete(q)?" · made it!":""),subject==1?22:23,CompanionCast.COLORS[(i+subject)%8],false,complete(q),()->play(index,false));}LinearLayout grid=GameUi.grid(this);GameUi.cells(grid,items,2,theme,120);body.addView(grid);}
 private boolean complete(SchoolContent.Question q){return progress.completed("creative-"+q.rewardKey());}
 void play(int index,boolean replay){replaying=replay;mission=Math.max(0,Math.min(SchoolContent.count(subject)-1,index));boolean reuse=screen.equals("mission")&&board!=null;screen="mission";question=SchoolContent.at(grade,subject,mission);if(!reuse){base(SchoolContent.SUBJECTS[subject]);root.removeView((View)body.getParent());LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(8),0,dp(8),dp(8));ScrollView missionScroll=new ScrollView(this);missionScroll.setFillViewport(true);missionScroll.addView(content);root.addView(missionScroll,new LinearLayout.LayoutParams(-1,0,1));guide=text("",12,false);content.addView(guide);prompt=text("",18,true);content.addView(prompt);FrameLayout frame=new FrameLayout(this);content.addView(frame,new LinearLayout.LayoutParams(-1,dp(Math.max(180,Math.min(300,getResources().getConfiguration().screenHeightDp-460)))));scene(frame);board=new SchoolPlayView(this,theme,reduced(),this::answer);frame.addView(board,new FrameLayout.LayoutParams(-1,-1));board.stage(stage);answers=new SchoolAnswers(this,theme,i->board.choose(i));content.addView(answers,new LinearLayout.LayoutParams(-1,-2));message=text("",14,false);message.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);content.addView(message);LinearLayout controls=new LinearLayout(this);controls.setBaselineAligned(false);controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(dp(8),dp(4),dp(8),dp(12));Button hear=button("Hear",()->narrator.speak(question.prompt));hear.setContentDescription("Hear this question using an installed offline voice");controls.addView(hear,new LinearLayout.LayoutParams(0,-2,1));Button replayButton=button("↻",()->play(mission,true));replayButton.setContentDescription("Replay this mission without spending or losing rewards");controls.addView(replayButton,new LinearLayout.LayoutParams(0,-2,1));controls.addView(button("Missions",()->missions(subject)),new LinearLayout.LayoutParams(0,-2,1));next=button("Next →",()->play((mission+1)%SchoolContent.count(subject),false));GameUi.primary(next,theme);controls.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);}guide.setText(SchoolContent.grade(grade)+" · Mission "+(mission+1)+" / "+SchoolContent.count(subject)+" · "+CompanionCast.NAMES[companion]);prompt.setText(question.prompt);boolean done=!replay&&complete(question);message.setText(done?question.explanation:"Drag a crystal to the ring, or tap an answer. Take your time.");next.setVisibility(done?View.VISIBLE:View.GONE);board.question(question,companion,done);answers.choices(question.choices,!done);}
 private void answer(boolean correct){if(question==null)return;if(!correct){message.setText("Let's explore the clue: "+question.explanation);sound.note(0);return;}replaying=false;answers.enableAnswers(false);boolean first=wallet.creativeCompletion(question.rewardKey());message.setText(question.explanation+(first?"  +1 star, +5 coins":"  Your first-clear reward is saved."));next.setVisibility(View.VISIBLE);if(question.subject==0)sound.win();else sound.tune(question.subject==1?new int[]{0,2,1}:new int[]{1,0,2});}
 private void back(){if(screen.equals("mission"))missions(subject);else if(screen.equals("missions"))subjects(grade);else if(screen.equals("subjects"))grades();else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onPause(){active=false;if(board!=null)board.stop();if(stage!=null)stage.pauseStage();narrator.stop();sound.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();active=true;long generation=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(generation!=resetGeneration){resetGeneration=generation;companion=0;grades();return;}if(theme!=null&&(new ThemeManager(this).dark!=theme.dark||(stage!=null&&stage.reducedMotion()!=reduced())))render();else{if(stage!=null)stage.resumeStage();if(board!=null&&question!=null)board.question(question,companion,!replaying&&complete(question));}}
 @Override protected void onSaveInstanceState(Bundle b){b.putBoolean("replaying",replaying);b.putString("screen",screen);b.putInt("grade",grade);b.putInt("subject",subject);b.putInt("mission",mission);super.onSaveInstanceState(b);}
 @Override protected void onDestroy(){if(board!=null)board.stop();narrator.close();sound.stop();db.close();super.onDestroy();}
}
